from datetime import datetime
import numpy as np

class MovieBookingSystem:
    def __init__(self):
        self._movies = []

    @property
    def movies(self):
        return self._movies

    @movies.setter
    def movies(self, value):
        self._movies = value

    def add_movie(self, name, price, start_time, end_time, n):
        movie = self._create_movie(name, price, start_time, end_time, n)
        self.movies.append(movie)

    def _create_movie(self, name, price, start_time, end_time, n):
        start_datetime = self._parse_time(start_time)
        end_datetime = self._parse_time(end_time)
        return {
            'name': name,
            'price': price,
            'start_time': start_datetime,
            'end_time': end_datetime,
            'seats': np.zeros((n, n))
        }

    @staticmethod
    def _parse_time(time_str):
        return datetime.strptime(time_str, '%H:%M')

    def book_ticket(self, name, seats_to_book):
        movie = self._find_movie_by_name(name)
        if movie is None:
            return "Movie not found."

        for seat in seats_to_book:
            if not self._is_seat_available(movie, seat):
                return "Booking failed."
            self._mark_seat_as_booked(movie, seat)

        return "Booking success."

    def _find_movie_by_name(self, name):
        for movie in self.movies:
            if movie['name'] == name:
                return movie
        return None

    def _is_seat_available(self, movie, seat):
        row, col = seat
        return movie['seats'][row][col] == 0

    def _mark_seat_as_booked(self, movie, seat):
        row, col = seat
        movie['seats'][row][col] = 1

    def available_movies(self, start_time, end_time):
        start_datetime = self._parse_time(start_time)
        end_datetime = self._parse_time(end_time)
        return self._get_movies_within_time_range(start_datetime, end_datetime)

    def _get_movies_within_time_range(self, start_time, end_time):
        available_list = []
        for movie in self.movies:
            if self._movie_is_within_range(movie, start_time, end_time):
                available_list.append(movie['name'])
        return available_list

    def _movie_is_within_range(self, movie, start_time, end_time):
        return start_time <= movie['start_time'] and movie['end_time'] <= end_time
